<?php declare(strict_types=1);
if(!$invitations->canSend())return;
$mailState=($calendarRecipientState['kind']??'')==='mail'?$calendarRecipientState:[];
$mailContext=$mailState||in_array(input($_POST,'action'),['preview-event-mail','send-event-mail'],true);$mailPost=$mailContext?$_POST:[];
$mailGroups=$mailContext?arrayInput($mailPost,'groups'):[($event['activity_kind']??'')==='board'?'board':'members'];$mailChannels=isset($mailPost['channels_present'])?arrayInput($mailPost,'channels'):['mail'];$isMeeting=in_array($event['activity_kind']??'',['assembly','board'],true);$mailPeople=arrayInput($mailPost,'recipients');
$mailSubject=input($mailPost,'subject','Einladung: '.$event['title']);$mailMessage=input($mailPost,'message');
?>
<div class="content"><details class="card" <?= $mailContext?'open':'' ?>><summary><?= e($calendarText('Einladung vorbereiten: E-Mail und Push')) ?></summary>
<p><?= e($calendarText('Wähle die Empfänger und danach den Versandweg. Bei Versammlungen stehen nur Personen der passenden Zielgruppe zur Auswahl. Gemeinsame Adressen erhalten eine Nachricht mit allen ausgewählten Namen in der Anrede. Ohne eigene Adresse wird die Mailadresse des ausdrücklich zugeordneten Familien-Beitragszahlers verwendet.')) ?></p>
<?php if(!$invitations->mailAllowed()): ?><p class="notice" role="status"><?= e($calendarText('Mailversand auf diesem PC gesperrt. Empfänger und Nachricht können hier als Vorschau geprüft werden.')) ?></p><?php endif ?>
<form method="post" data-calendar-recipient-form="mail"><?= csrf().hidden('action','preview-event-mail').hidden('id',$event['id']) ?>
<fieldset data-invitation-groups><legend><?= e($calendarText('Empfänger')) ?></legend><?php foreach($invitations->groupsFor($event['id']) as $value=>$label): ?><label class="check"><input class="check" type="checkbox" name="groups[]" value="<?= $value ?>" <?= in_array($value,$mailGroups,true)?'checked':'' ?>><?= e($calendarText($label)) ?></label><?php endforeach ?>
<details data-invitation-people <?= $mailState||in_array('selected',$mailGroups,true)?'open':'' ?>><summary><?= e($calendarText('Einzelne Personen auswählen')) ?></summary><?= \Kulturhus\Verein\CalendarRecipientPicker::render($invitations,$event['id'],'mail',$mailPeople,$mailState,$calendarText) ?></details></fieldset>
<?= hidden('channels_present','1') ?><fieldset><legend><?= e($calendarText('Wie soll die Einladung ankommen?')) ?></legend><label class="check"><input class="check" type="checkbox" name="channels[]" value="mail" <?= in_array('mail',$mailChannels,true)?'checked':'' ?>><?= e($calendarText('E-Mail')) ?></label><?php if($isMeeting): ?><label class="check"><input class="check" type="checkbox" name="channels[]" value="push" <?= in_array('push',$mailChannels,true)?'checked':'' ?>><?= e($calendarText('Push auf aktivierten Geräten')) ?></label><p><?= e($calendarText('Push erreicht nur berechtigte Personen mit eingeschalteten Versammlungshinweisen und einem aktivierten Gerät. Die Vorschau zeigt die erreichbaren Personen und Geräte.')) ?></p><?php endif ?></fieldset><label><?= e($calendarText('Betreff')) ?><input class="form-control" name="subject" value="<?= e($mailSubject) ?>" maxlength="200" required></label><label><?= e($calendarText('Nachricht')) ?><textarea class="form-control" name="message" rows="4" maxlength="10000"><?= e($mailMessage) ?></textarea></label><p><?= e($calendarText('Datum, Uhrzeit, Ort und gespeicherte Tagesordnung werden aus dem gespeicherten Termin ergänzt.')) ?></p><button class="btn btn-outline theme-secondary secondary"><?= e($calendarText('Empfänger und Nachricht prüfen')) ?></button></form>
<?php if($invitationPreview): ?><section aria-label="<?= e($calendarText('Versandvorschau')) ?>"><h3><?= e($calendarFormat('Versandvorschau · {count} E-Mail-Adressen',['count'=>$invitationPreview['mail_count']])) ?></h3><p><?= e($calendarFormat('{duplicates} doppelte Adressen zusammengefasst · {missing} ohne gültige E-Mail ausgelassen.',['duplicates'=>$invitationPreview['duplicates'],'missing'=>$invitationPreview['missing']])) ?></p><p><?= e($calendarFormat('{people} Personen auf {devices} Geräten per Push erreichbar.',['people'=>count($invitationPreview['push_contacts']),'devices'=>$invitationPreview['push_devices']])) ?></p><?php if($invitationPreview['additional_attendees']): ?><p><?= e($calendarFormat('Zusätzlich erhalten {count} ausgewählte Personen Zugang zu diesem Termin im Vereinsportal.',['count'=>count($invitationPreview['additional_attendees'])])) ?></p><?php endif ?><h4><?= e($invitationPreview['subject']) ?></h4><p><?= nl2br(e($invitationPreview['body'])) ?></p><details><summary><?= e($calendarText('Empfängerliste anzeigen')) ?></summary><ul><?php foreach($invitationPreview['recipients'] as $recipient): ?><li><?= e($recipient['name'].' · '.$recipient['email']) ?> <?= e($calendarText('– Anrede:')) ?> <?= e('Guten Tag '.implode(', ',$recipient['names']).',') ?></li><?php endforeach ?></ul></details>
<form method="post"><?= csrf().hidden('action','send-event-mail').hidden('id',$event['id']).hidden('subject',$mailSubject).hidden('message',$mailMessage).hidden('preview_hash',$invitationPreview['preview_hash']).hidden('request_key',bin2hex(random_bytes(16))) ?><?= hidden('channels_present','1') ?><?php foreach($mailChannels as $channel)echo hidden('channels[]',$channel);foreach($mailGroups as $group)echo hidden('groups[]',$group);echo \Kulturhus\Verein\CalendarRecipientPicker::confirmation($mailPeople); ?><button class="btn btn-solid theme-primary" <?= (in_array('mail',$mailChannels,true)&&!$invitations->mailAllowed())||(!$invitationPreview['mail_count']&&!$invitationPreview['push_devices'])?'disabled':'' ?>><?= e($calendarText(in_array('mail',$mailChannels,true)&&!$invitations->mailAllowed()?'E-Mail-Versand auf diesem PC gesperrt':'Geprüfte Einladung jetzt beauftragen')) ?></button></form></section><?php endif ?>
</details></div>

<?php $deliveryStatuses=$invitations->deliveryStatus($event['id']);if($deliveryStatuses): ?><div class="content"><section class="card"><h3><?= e($calendarText('Mailversand dieses Termins')) ?></h3><?php foreach($deliveryStatuses as $deliveryStatus): ?><p><?= e($calendarText(['pending'=>'Vorgemerkt','sending'=>'Versand läuft / Ergebnis prüfen','sent'=>'Vom Mailserver angenommen','uncertain'=>'Versandergebnis unklar – prüfen','skipped'=>'Nicht versendet – Termin oder Empfänger erneut prüfen'][$deliveryStatus['status']])) ?>: <?= (int)$deliveryStatus['total'] ?></p><?php endforeach ?></section></div><?php endif ?>
